package com.example.bookmyticket.service;
import com.example.bookmyticket.dto.*; import com.example.bookmyticket.entity.*; import com.example.bookmyticket.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Service public class BookingService {
 private final MovieShowRepository shows; private final BookingRepository bookings; private final BookedSeatRepository seats;
 public BookingService(MovieShowRepository s,BookingRepository b,BookedSeatRepository r){shows=s;bookings=b;seats=r;}
 public List<SeatDto> getSeats(Long showId){MovieShow show=shows.findById(showId).orElseThrow(()->new IllegalArgumentException("Show not found")); Set<String> taken=new HashSet<>(); seats.findByMovieShowId(showId).forEach(x->taken.add(x.getSeatNumber())); List<SeatDto> out=new ArrayList<>(); for(int r=0;r<6;r++)for(int n=1;n<=8&&out.size()<show.getTotalSeats();n++){String name=""+(char)('A'+r)+n;out.add(new SeatDto(name,taken.contains(name)));} return out;}
 @Transactional public BookingDto create(BookingRequest req){MovieShow show=shows.findById(req.showId()).orElseThrow(()->new IllegalArgumentException("Show not found")); List<String> chosen=req.seats().stream().map(x->x.trim().toUpperCase()).distinct().toList(); if(chosen.size()!=req.seats().size())throw new IllegalArgumentException("Duplicate seat selected"); Set<String> valid=new HashSet<>(); for(int r=0;r<6;r++)for(int n=1;n<=8;n++)valid.add(""+(char)('A'+r)+n); for(String seat:chosen){if(!valid.contains(seat))throw new IllegalArgumentException("Invalid seat: "+seat);if(seats.existsByMovieShowIdAndSeatNumber(show.getId(),seat))throw new IllegalArgumentException("Seat "+seat+" is already booked. Choose another seat.");} BigDecimal total=show.getTicketPrice().multiply(BigDecimal.valueOf(chosen.size())); Booking booking=bookings.save(new Booking("BMT"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),req.customerName().trim(),req.email().trim().toLowerCase(),show,total,LocalDateTime.now())); for(String seat:chosen)seats.save(new BookedSeat(show,booking,seat)); return dto(booking,chosen);}
 public List<BookingDto> history(String email){return bookings.findByEmailIgnoreCaseOrderByBookedAtDesc(email).stream().map(b->{List<String> own=seats.findByMovieShowId(b.getMovieShow().getId()).stream().filter(s->Objects.equals(s.getBooking().getId(),b.getId())).map(BookedSeat::getSeatNumber).toList();return dto(b,own);}).toList();}
 private BookingDto dto(Booking b,List<String> chosen){MovieShow s=b.getMovieShow();return new BookingDto(b.getBookingCode(),b.getCustomerName(),b.getEmail(),s.getMovie().getTitle(),s.getTheatre().getName(),s.getStartTime(),chosen,b.getTotalAmount(),b.getBookedAt());}
}
